ROOT=Path(__file__).parent;OUT=ROOT/'dist';BASE='https://www.compakt-service.de';E=html.escape;routes=[]
FAQ=[('Welche Leistungen bietet COMPAKT Service an?','Wir verbinden Gebäudereinigung, Wachschutz, Winterdienst, Graffiti-Entfernung, Hausmeisterdienst, Grünflächenpflege, Immobilienservice, Alltagshilfe und Drohnenservice. Sie können einzelne Leistungen oder eine abgestimmte Betreuung anfragen.'),('Für wen arbeitet COMPAKT?','Wir betreuen Unternehmen, Hausverwaltungen, öffentliche Einrichtungen und private Auftraggeber. Umfang und Organisation richten sich nach Ihrem Objekt und den gewünschten Leistungen.'),('In welchen Regionen sind Sie tätig?','Unser Standort ist Fürstenwalde/Spree in Brandenburg. Anfragen für Berlin, Sachsen und Sachsen-Anhalt prüfen und koordinieren wir innerhalb der FORM Gruppe. Die Verfügbarkeit wird für das jeweilige Objekt und die benötigte Leistung abgestimmt.'),('Kann ich mehrere Leistungen kombinieren?','Ja. Beispielsweise lassen sich Reinigung, Hausmeisterdienst, Grünflächenpflege und Winterdienst zusammen organisieren. So können Aufgaben und Zuständigkeiten aufeinander abgestimmt werden.'),('Wie erhalte ich ein Angebot?','Nennen Sie uns Standort, Objektart, gewünschte Leistung und ungefähren Umfang. Vorhandene Fotos, Flächenangaben oder ein Leistungsverzeichnis helfen bei der Vorbereitung. Wir klären die Details persönlich und stimmen bei Bedarf eine Besichtigung ab.'),('Gehört COMPAKT zur FORM Gruppe?','Ja. COMPAKT wurde 2025 von der FORM Gruppe übernommen. Dadurch können zusätzliche Kompetenzen eingebunden werden, etwa die Sicherheitsleistungen der WSG und der FORM Drohnenservice.')]
def media(file,alt,ai=False,cls='',eager=False):return f'<div class="media {cls}"><img src="/assets/{E(file)}" alt="{E(alt)}" width="1200" height="800" loading="{"eager" if eager else "lazy"}" decoding="async">'+('<span class="badge">KI-generiert</span>' if ai else '')+'</div>'
def btn(url,label,cls=''):return f'<a class="btn {cls}" href="{url}">{label}</a>'
def crumbs(label):return f'<div class="breadcrumb"><a href="/">Start</a> &nbsp;/&nbsp; {E(label)}</div>'
def cta():return '<section class="cta"><div class="wrap"><h2>Was dürfen wir für<br>Sie übernehmen?</h2>'+btn('/kontakt/','Projekt gemeinsam besprechen','white')+'</div></section>'
def group():return '<section class="groupband"><div class="wrap group-inner"><a href="https://www.form-gruppe.de/" aria-label="FORM Gruppe besuchen"><img src="/assets/group.webp" alt="FORM Gruppe" loading="lazy"></a><p><strong>Eigenständig. Und gemeinsam stärker.</strong>COMPAKT ist ein Unternehmen der FORM Gruppe. Für Sie heißt das: regionale Nähe und das Know-how eines vielseitigen Unternehmensverbunds.</p><a class="text-link" href="/ueber-uns/">Mehr über uns</a></div></section>'
def faq(items=FAQ):return '<div class="faq">'+''.join(f'<details><summary>{E(q)}</summary><p>{E(a)}</p></details>' for q,a in items)+'</div>'
def schemafaq(items):return {'@context':'https://schema.org','@type':'FAQPage','mainEntity':[{'@type':'Question','name':q,'acceptedAnswer':{'@type':'Answer','text':a}} for q,a in items]}
ORG={'@context':'https://schema.org','@type':'LocalBusiness','name':'COMPAKT SERVICE GmbH','url':BASE,'logo':BASE+'/assets/logo.svg','telephone':'+49 3361 747888-0','email':'info@compakt-service.de','address':{'@type':'PostalAddress','streetAddress':'Gewerbeparkring 1','postalCode':'15517','addressLocality':'Fürstenwalde/Spree','addressCountry':'DE'},'areaServed':['Brandenburg','Berlin','Sachsen','Sachsen-Anhalt']}
