def posturl(p):return ('/compakt-news-eintrag/' if p.get('archive') else '/news/')+p['slug']+'/'
def postcards(items):return '<div class="post-grid">'+''.join(f'<article class="post-card" data-post data-search="{E((p["title"]+" "+p["intro"]).lower())}" data-category="{E(p["category"])}"><a href="{posturl(p)}">'+media(p['image'],p.get('image_alt',p['title']),p.get('ai',False))+f'<span class="meta">{date.fromisoformat(p["date"]).strftime("%d.%m.%Y")} · {E(p["category"])}</span><h3>{E(p["title"])}</h3><p>{E(p["intro"][:190])}</p><span class="text-link">Beitrag lesen</span></a></article>' for p in items)+'</div>'
home='''<section class="hero"><div class="wrap hero-grid"><div class="hero-copy"><span class="eyebrow">COMPAKT SERVICE · FÜRSTENWALDE / SPREE</span><h1>Wir kümmern uns.<br><span>Sie haben<br>den Kopf frei.</span></h1><p class="lead">Reinigung, Sicherheit und Immobilienservice. Persönlich vor Ort – mit der Stärke der FORM Gruppe im Rücken.</p><div class="actions">'''+btn('/leistungen/','Leistungen entdecken <span aria-hidden="true">↗</span>')+btn('/kontakt/','Projekt anfragen','secondary')+'''</div><div class="hero-bottom"><span class="small-line"></span><p>Für Unternehmen, Hausverwaltungen<br>und Menschen in unserer Region.</p></div></div><div class="hero-visual"><div class="hero-photo"><img src="/assets/hero.webp" width="1600" height="1067" alt="COMPAKT Mitarbeiter plant einen Einsatz am Firmenfahrzeug" fetchpriority="high"><span class="image-caption">UNSER TEAM. IHR OBJEKT. ALLES IM BLICK.</span></div><a class="hero-stamp" href="/ueber-uns/"><span>Regional verwurzelt.</span><strong>Gemeinsam<br>stärker.</strong><img src="/assets/group.webp" alt="FORM Gruppe" width="120" height="70"></a></div></div></section><div class="trust"><div class="wrap trust-grid"><div><span class="trust-index">01</span><strong>Saubere Räume</strong>Reinigung mit System</div><div><span class="trust-index">02</span><strong>Sichere Gebäude</strong>Schutz mit der WSG</div><div><span class="trust-index">03</span><strong>Gepflegte Immobilien</strong>Innen und außen betreut</div><div><span class="trust-index">04</span><strong>Persönliche Betreuung</strong>Kurze Wege, klare Absprachen</div></div></div><section class="section services-section"><div class="wrap"><div class="section-head"><div><span class="eyebrow">01 / UNSERE LEISTUNGEN</span><h2>Ihr Gebäude.<br><span class="accent">Unsere Verantwortung.</span></h2></div><p>Vom sauberen Treppenhaus bis zum sicheren Firmengelände: Wählen Sie die Unterstützung, die zu Ihrem Alltag passt.</p></div>'''+service_cards()+'''</div></section><section class="section pale about-section"><div class="wrap split"><div class="team-frame"><img class="big-image" src="/assets/service-3.webp" alt="WSG Sicherheitsmitarbeiter bei einer Objektkontrolle" loading="lazy" width="1024" height="683"><span class="team-caption">COMPAKT + WSG · EIN STARKES NETZWERK</span></div><div><span class="eyebrow">02 / EIN UNTERNEHMEN DER FORM GRUPPE</span><h2>Die Nähe bleibt.<br><span class="accent">Die Stärke wächst.</span></h2><p class="lead">Ein regionaler Ansprechpartner. Die Möglichkeiten einer ganzen Unternehmensgruppe.</p><p>COMPAKT gehört seit der Übernahme 2025 zur FORM Gruppe. Für Ihr Objekt verbinden wir unsere Betreuung in Fürstenwalde mit ergänzenden Kompetenzen – vom Sicherheitsdienst der WSG bis zum FORM Drohnenservice.</p><div class="partner-logos"><img src="/assets/group.webp" alt="FORM Gruppe" loading="lazy"><span aria-hidden="true">+</span><img src="/assets/wsg.svg" alt="WSG" loading="lazy"></div>'''+btn('/ueber-uns/','Unser Unternehmen kennenlernen','dark')+'''</div></div></section><section class="section process-section"><div class="wrap"><div class="section-head"><div><span class="eyebrow">03 / SO STARTET DIE ZUSAMMENARBEIT</span><h2>Gute Betreuung beginnt<br>mit einem guten Gespräch.</h2></div><a class="text-link" href="/kontakt/">Lernen wir uns kennen</a></div><div class="process-grid"><article><span>01</span><h3>Bedarf verstehen.</h3><p>Sie erzählen uns von Ihrem Objekt. Wir klären Aufgaben, Flächen und Ihre Wünsche – bei Bedarf direkt vor Ort.</p></article><article><span>02</span><h3>Leistungen abstimmen.</h3><p>Gemeinsam legen wir Umfang, Intervalle und Zuständigkeiten fest. Sie erhalten ein Angebot für Ihren konkreten Bedarf.</p></article><article><span>03</span><h3>Verlässlich betreuen.</h3><p>Wir organisieren die vereinbarten Arbeiten und bleiben für Rückfragen und Anpassungen persönlich erreichbar.</p></article></div></div></section><section class="section regions"><div class="wrap"><span class="eyebrow">04 / UNSERE REGIONEN</span><h2>In Brandenburg zu Hause.<br>Im Netzwerk verbunden.</h2><p class="lead">Unser Ausgangspunkt ist Fürstenwalde/Spree. Anfragen für weitere Regionen koordinieren wir objektbezogen innerhalb der FORM Gruppe.</p>'''+region_tiles()+'''</div></section><section class="section"><div class="wrap"><div class="section-head"><div><span class="eyebrow">05 / NEWS & RATGEBER</span><h2>Wissen, das weiterhilft.</h2></div><a class="text-link" href="/news/">Alle Beiträge entdecken</a></div>'''+postcards(posts[:3])+'''</div></section><section class="section pale"><div class="wrap faq-layout"><div><span class="eyebrow">06 / HÄUFIGE FRAGEN</span><h2>Was Sie<br>wissen möchten.</h2><p class="muted">Von der ersten Anfrage bis zur laufenden Betreuung: Hier finden Sie Antworten.</p><a class="text-link" href="/kontakt/">Ihre Frage persönlich besprechen</a></div>'''+faq()+'''</div></section>'''+group()+cta()
page('/','Reinigung, Sicherheit & Immobilienservice in Fürstenwalde','COMPAKT Service: neun Leistungen rund um Ihre Immobilie. In Fürstenwalde verwurzelt, mit der FORM Gruppe für Brandenburg, Berlin, Sachsen und Sachsen-Anhalt.',home,[schemafaq(FAQ)])
page('/leistungen/','Unsere Leistungen rund um Ihre Immobilie','Gebäudereinigung, Wachschutz, Hausmeisterdienst, Winterdienst und mehr: Entdecken Sie alle neun Leistungsbereiche von COMPAKT Service.','<section class="page-hero"><div class="wrap">'+crumbs('Leistungen')+'<span class="eyebrow">Alles im Blick</span><h1>Ihr Bedarf.<br>Unsere Leistungen.</h1><p class="lead">Neun Bereiche. Ein gemeinsamer Anspruch: Sie im Alltag zuverlässig zu entlasten.</p></div></section><section class="section"><div class="wrap">'+service_cards()+'</div></section>'+cta(),section='leistungen')
for s in SERVICES:
 slug,name,claim,img,description,sections,tags=s
 sf=[(f'Wie wird {name} für mein Objekt geplant?','Wir besprechen Standort, Nutzung, Flächen und Ihren gewünschten Leistungsumfang. Bei Bedarf erfolgt eine Besichtigung. Auf dieser Grundlage stimmen wir Aufgaben, Ausführung und Termine ab.'),('Kann ich weitere Leistungen ergänzen?','Ja. Die Betreuung lässt sich mit anderen Leistungen aus unserem Angebot kombinieren. Wir prüfen gemeinsam, welche Zusammenstellung für Ihre Immobilie sinnvoll ist.'),('Ist die Leistung an meinem Standort verfügbar?','Fragen Sie uns mit der genauen Objektadresse an. Neben Fürstenwalde und dem Brandenburger Umfeld prüfen wir Anfragen für Berlin, Sachsen und Sachsen-Anhalt im Verbund der FORM Gruppe.')]
 body='<section class="page-hero"><div class="wrap">'+crumbs(name)+'<div class="split"><div><span class="eyebrow">'+name+'</span><h1>'+claim+'</h1><p class="lead">'+description+'</p>'+btn('/kontakt/?leistung='+slug,'Leistung anfragen')+'</div>'+media(img,name,slug in ['grafittientfernung','gruenflaechenpflege'],eager=True)+'</div><div class="tagrow">'+''.join('<span class="tag">'+x+'</span>' for x in tags)+'</div></div></section><section class="section"><div class="wrap"><div class="prose">'+''.join('<h2>'+h+'</h2><p>'+t+'</p>' for h,t in sections)
